import base64, hashlib, sys, urllib.request
from pathlib import Path

BASE_URL="https://raw.githubusercontent.com/8hatay9-commits/ibo/ad31b08280dbea26ad68454a3d45c20fe3cdaf48/flashbot/releases/v3.9.0/daemon.py"
BASE_GIT_BLOB_SHA1="67289d1f38bd3e4db9580948b02319436d78fd19"

raw=urllib.request.urlopen(BASE_URL,timeout=30).read()
got=hashlib.sha1(f"blob {len(raw)}\0".encode()+raw).hexdigest()
if got!=BASE_GIT_BLOB_SHA1:
    raise RuntimeError(f"pinned V3.9.0 daemon mismatch: {got}")
src=raw.decode("utf-8")
dec=lambda s:base64.b64decode(s).decode("utf-8")

old=dec("ZGVmIHdyaXRlX3N0YXRlKG9iaik6CiAgICB0bXAgPSBTVVBfU1RBVEUud2l0aF9zdWZmaXgoIi50bXAiKQogICAgdG1wLndyaXRlX3RleHQoanNvbi5kdW1wcyhvYmosIGluZGVudD0yKSwgZW5jb2Rpbmc9InV0Zi04IikKICAgIHRtcC5yZXBsYWNlKFNVUF9TVEFURSkK")
new=dec("")
if old not in src:
    raise RuntimeError("V3.9.6 supervisor state-write marker not found")
src=src.replace(old,new,1)

old=dec("ICAgIHJldHVybiBzcmMKCmRlZiBydW5fd29ya2VyKCk6Cg==")
new=dec("")
if old not in src:
    raise RuntimeError("V3.9.6 patch-core return marker not found")
src=src.replace(old,new,1)

src=src.replace('src = src.replace("FLASHBOT-PRODUCTION-V3.7.0","FLASHBOT-PRODUCTION-V3.8.4",1)',
                'src = src.replace("FLASHBOT-PRODUCTION-V3.7.0","FLASHBOT-PRODUCTION-V3.9.6",1)',1)
src=src.replace("FLASHBOT-SUPERVISOR-V3.8.4","FLASHBOT-SUPERVISOR-V3.9.6")

exec(compile(src,BASE_URL,"exec"),{"__name__":"__main__","__file__":str(Path(__file__).resolve())})
